<script setup>
import { ref, computed, watch, onUnmounted } from 'vue'
import { Search, ShoppingBag, Heart, ArrowUpRight, ArrowRight, X, Plus, Minus, Truck, ShieldCheck, Music2, Menu, Check, SlidersHorizontal } from 'lucide-vue-next'
const products = [
 {id:101,name:'Camisa Roots',category:'Camisas',label:'Vista a força das raízes',description:'Estampa autoral inspirada nas raízes do reggae. A identidade Domora para acompanhar o seu ritmo.',price:89.9,img:'/images/camisa-roots.svg',tag:'Mais amada'},
 {id:102,name:'Pendrive Roots & Culture',category:'Pendrives',label:'Uma seleção para entrar na frequência',description:'Uma seleção de reggae roots para levar a sua vibe aonde você for. Repertório, capacidade e compatibilidade serão informados no catálogo definitivo.',price:59.9,img:'/images/pendrive-roots.svg',tag:'Seleção Domora'},
 {id:103,name:'Camisa One Love',category:'Camisas',label:'Uma mensagem que a gente veste',description:'Tons naturais e uma mensagem de união. Uma camisa para quem vive o reggae dentro e fora dos shows.',price:89.9,img:'/images/camisa-one-love.svg',tag:''},
 {id:104,name:'Pendrive Dub Session',category:'Pendrives',label:'Graves, ecos e boas vibrações',description:'Uma seleção voltada à atmosfera do dub. Repertório, capacidade e compatibilidade serão informados no catálogo definitivo.',price:69.9,img:'/images/pendrive-dub.svg',tag:'Novo'},
 {id:105,name:'Camisa Sound System',category:'Camisas',label:'O som é parte de quem você é',description:'Uma homenagem à cultura sound system em uma estampa exclusiva Domora. Do encontro com os amigos ao próximo show.',price:99.9,img:'/images/camisa-sound.svg',tag:'Original Domora'},
 {id:106,name:'Pendrive Good Vibes',category:'Pendrives',label:'Seu dia merece essa trilha',description:'Uma seleção de reggae para acompanhar os bons momentos. Repertório, capacidade e compatibilidade serão informados no catálogo definitivo.',price:59.9,img:'/images/pendrive-vibes.svg',tag:''}
]
function read(key, fallback){try{return JSON.parse(localStorage.getItem(key)) ?? fallback}catch{return fallback}}
const cart = ref(read('domora-cart',[]).filter(i=>products.some(p=>p.id===i.id)&&Number.isInteger(i.qty)&&i.qty>0))
const favorites = ref(read('domora-favorites',[]))
watch(cart,v=>localStorage.setItem('domora-cart',JSON.stringify(v)),{deep:true})
watch(favorites,v=>localStorage.setItem('domora-favorites',JSON.stringify(v)),{deep:true})
const category=ref('Todos'), search=ref(''), sort=ref('featured'), onlyFavorites=ref(false), drawer=ref(false), mobileMenu=ref(false), detail=ref(null), checkout=ref(false), orderDone=ref(false), toast=ref(''), subscribed=ref(false), email=ref('')
let timer
function notify(text){toast.value=text;clearTimeout(timer);timer=setTimeout(()=>toast.value='',3000)}
onUnmounted(()=>clearTimeout(timer))
const money=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const filtered=computed(()=>{
 let list=products.filter(p=>(category.value==='Todos'||p.category===category.value)&&(!onlyFavorites.value||favorites.value.includes(p.id))&&p.name.toLowerCase().includes(search.value.toLowerCase()))
 if(sort.value==='low')list.sort((a,b)=>a.price-b.price)
 if(sort.value==='high')list.sort((a,b)=>b.price-a.price)
 return list
})
const items=computed(()=>cart.value.map(i=>({...products.find(p=>p.id===i.id),qty:i.qty})))
const count=computed(()=>cart.value.reduce((s,i)=>s+i.qty,0))
const total=computed(()=>items.value.reduce((s,i)=>s+i.price*i.qty,0))
const shipping=computed(()=>total.value>=999||!count.value?0:39.9)
function add(p){const item=cart.value.find(i=>i.id===p.id);if(item)item.qty++;else cart.value.push({id:p.id,qty:1});notify(`${p.name} adicionado à sacola`)}
function quantity(id,delta){const i=cart.value.find(i=>i.id===id);i.qty+=delta;if(i.qty<=0)cart.value=cart.value.filter(i=>i.id!==id)}
function favorite(id){favorites.value=favorites.value.includes(id)?favorites.value.filter(i=>i!==id):[...favorites.value,id]}
function scrollCollection(){document.getElementById('colecao').scrollIntoView({behavior:'smooth'})}
function focusSearch(){scrollCollection();document.getElementById('busca').focus()}
function choose(c){category.value=c;onlyFavorites.value=false;mobileMenu.value=false;document.getElementById('colecao').scrollIntoView({behavior:'smooth'})}
function finish(){cart.value=[];checkout.value=false;orderDone.value=true}
watch([drawer, detail, checkout, orderDone],()=>{document.body.style.overflow=drawer.value||detail.value||checkout.value||orderDone.value?'hidden':''})
function escape(e){if(e.key==='Escape'){orderDone.value=false;checkout.value=false;detail.value=null;drawer.value=false;mobileMenu.value=false}}
window.addEventListener('keydown',escape)
onUnmounted(()=>window.removeEventListener('keydown',escape))
</script>

<template>
 <div class="announcement">Reggae no som. Reggae no estilo. <span>Frete grátis a partir de R$ 999</span><ArrowUpRight :size="13"/></div>
 <header>
  <a class="logo" href="#" aria-label="Domora início">domora<span>®</span></a>
  <nav :class="{open:mobileMenu}"><a href="#colecao" @click.prevent="choose('Todos')">Coleção</a><a href="#colecao" @click.prevent="choose('Camisas')">Camisas</a><a href="#colecao" @click.prevent="choose('Pendrives')">Pendrives</a><a href="#essencia" @click="mobileMenu=false">Nossa essência</a></nav>
  <div class="header-actions"><button aria-label="Buscar produtos" @click="focusSearch()"><Search :size="21"/></button><button aria-label="Ver favoritos" :class="{active:onlyFavorites}" @click="onlyFavorites=!onlyFavorites;scrollCollection()"><Heart :size="21"/><sup v-if="favorites.length">{{favorites.length}}</sup></button><button class="bag" aria-label="Abrir sacola" @click="drawer=true"><ShoppingBag :size="21"/><span>{{ count }}</span></button><button class="mobile-toggle" aria-label="Menu" @click="mobileMenu=!mobileMenu"><Menu :size="22"/></button></div>
 </header>
 <main>
  <section class="hero">
   <div class="hero-visual"><img src="/images/hero-roots.svg" alt="Camisa Roots & Culture, disco de reggae e pendrive Good Vibes da Domora" fetchpriority="high"/></div>
   <div class="hero-content"><div class="eyebrow"><span></span> VIVA NA SUA FREQUÊNCIA</div><h1><span>Vista a raiz.</span><span>Leve a</span><span>vibração.</span></h1><p>Camisas que vestem a cultura. Sons que conectam.<br>Leve a energia do reggae com você.</p><a class="button cream" href="#colecao">Explore a coleção <ArrowUpRight :size="19"/></a><div class="hero-foot">NOVA COLEÇÃO <span>—</span> ROOTS & CULTURE</div></div>
   <a class="hero-caption" href="#colecao">ROOTS. CULTURE. DOMORA.<span>Conheça a coleção <ArrowUpRight :size="18"/></span></a><div class="hero-number">ESTILO INDEPENDENTE <span>•</span> ALMA REGGAE</div>
  </section>
  <div class="benefits"><div><Truck/><span>Entrega para todo o Brasil</span></div><div><ShieldCheck/><span>Boas escolhas, boas vibrações</span></div><div><Music2/><span>Reggae no seu dia a dia</span></div><a href="#essencia">Feito de ritmo e raízes <ArrowUpRight :size="16"/></a></div>
  <section class="collection" id="colecao">
   <div class="section-top"><div><div class="eyebrow muted">DA NOSSA VIBE PARA A SUA</div><h2>Encontre a sua frequência.</h2></div><p>Camisas com identidade. Pendrives com reggae.<br>Uma cultura que acompanha você.</p></div>
   <div class="filters"><div class="tabs"><button v-for="c in ['Todos','Camisas','Pendrives']" :key="c" :class="{selected:category===c}" @click="category=c">{{c}} <span v-if="c==='Todos'">{{products.length}}</span></button></div><div class="filter-tools"><label class="search"><Search :size="17"/><input id="busca" v-model="search" placeholder="Buscar na Domora" aria-label="Buscar na Domora"/></label><label class="sort"><SlidersHorizontal :size="16"/><select v-model="sort" aria-label="Ordenar produtos"><option value="featured">Destaques</option><option value="low">Menor preço</option><option value="high">Maior preço</option></select></label></div></div>
   <div v-if="onlyFavorites" class="favorite-filter">Seus favoritos <button @click="onlyFavorites=false">Mostrar todos <X :size="14"/></button></div>
   <div class="product-grid"><article v-for="p in filtered" :key="p.id" class="product"><div class="product-image"><button class="image-button" @click="detail=p" :aria-label="`Ver ${p.name}`"><img :src="p.img" :alt="p.name" loading="lazy"/></button><span v-if="p.tag" class="tag">{{p.tag}}</span><button class="heart" :class="{saved:favorites.includes(p.id)}" :aria-label="favorites.includes(p.id)?'Remover dos favoritos':'Salvar nos favoritos'" :aria-pressed="favorites.includes(p.id)" @click="favorite(p.id)"><Heart :size="18" :fill="favorites.includes(p.id)?'currentColor':'none'"/></button><button class="quick-add" @click="add(p)">Adicionar à sacola <Plus :size="17"/></button></div><div class="product-meta"><div><span class="category">{{p.category}}</span><button class="product-title" @click="detail=p">{{p.name}}</button><p>{{p.label}}</p></div><button class="round-add" :aria-label="`Adicionar ${p.name}`" @click="add(p)"><Plus :size="19"/></button></div><div class="price">{{money(p.price)}} <span>ou 6x de {{money(p.price/6)}}</span></div></article></div>
   <div v-if="!filtered.length" class="empty"><Search :size="30"/><h3>Nenhum produto por aqui.</h3><p>Experimente outra busca ou categoria.</p><button class="button green" @click="search='';category='Todos';onlyFavorites=false">Ver toda a coleção</button></div>
  </section>
  <section class="story" id="essencia"><div class="story-image"><div class="culture-art" aria-label="One love. One vibe."><div>ONE<span>LOVE.</span>ONE<span>VIBE.</span></div><Music2 :size="55" aria-hidden="true"/></div><span>RAÍZES NA CULTURA. ALMA NO REGGAE.</span></div><div class="story-copy"><div class="eyebrow muted">O JEITO DOMORA</div><h2>Uma cultura.<br>Muitas vozes.<br>A mesma <em>vibração.</em></h2><p>A Domora nasceu para quem sente o reggae no peito e leva essa energia para a vida. Uma conexão entre música, estilo e boas vibrações.</p><p>Das camisas aos pendrives com seleções de reggae, cada escolha é um convite para expressar a sua identidade e manter a cultura pulsando.</p><a href="#colecao">Faça parte dessa vibe <ArrowUpRight :size="19"/></a></div></section>
  <section class="newsletter"><div><div class="eyebrow muted">FIQUE MAIS PERTO</div><h2>A próxima vibe chega aqui.</h2><p>Novas estampas, seleções de reggae e novidades da Domora no seu e-mail.</p></div><form @submit.prevent="subscribed=true"><label for="email">Seu melhor e-mail</label><div class="email-input"><input id="email" type="email" v-model="email" required placeholder="voce@email.com" :disabled="subscribed"/><button :disabled="subscribed" aria-label="Inscrever-se"><Check v-if="subscribed"/><ArrowRight v-else/></button></div><small>{{subscribed?'Cadastro demonstrativo concluído. Obrigado pelo interesse!':'Ao se inscrever, você aceita receber novidades da Domora.'}}</small></form></section>
 </main>
 <footer><div><a href="#" class="logo">domora<span>®</span></a><p>Vista a cultura. Leve o reggae.</p></div><div class="footer-links"><a href="#colecao">Nossa coleção</a><a href="#essencia">Nossa essência</a><button @click="drawer=true">Minha sacola</button></div><div class="footer-bottom"><span>© {{new Date().getFullYear()}} Domora. Projeto demonstrativo.</span><span>Na frequência das boas vibrações. ↗</span></div></footer>
 <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Check :size="18"/>{{toast}}</div></Transition>
 <div v-if="drawer" class="overlay" @click.self="drawer=false"><aside class="cart-panel" role="dialog" aria-modal="true" aria-labelledby="cart-title"><div class="panel-header"><h2 id="cart-title">Sua sacola <span>({{count}})</span></h2><button aria-label="Fechar sacola" @click="drawer=false"><X/></button></div><template v-if="items.length"><p class="shipping-note">{{total>=999?'Seu pedido tem frete grátis!':`Faltam ${money(999-total)} para ganhar frete grátis.`}}</p><div class="cart-items"><article v-for="i in items" :key="i.id" class="cart-item"><img :src="i.img" :alt="i.name"/><div><h3>{{i.name}}</h3><p>{{money(i.price)}}</p><div class="quantity"><button :aria-label="`Diminuir ${i.name}`" @click="quantity(i.id,-1)"><Minus :size="14"/></button><span>{{i.qty}}</span><button :aria-label="`Aumentar ${i.name}`" @click="quantity(i.id,1)"><Plus :size="14"/></button></div></div><button class="remove" :aria-label="`Remover ${i.name}`" @click="cart=cart.filter(p=>p.id!==i.id)"><X :size="16"/></button></article></div><div class="cart-total"><div>Subtotal <span>{{money(total)}}</span></div><div>Frete demonstrativo <span>{{shipping?money(shipping):'Grátis'}}</span></div><div class="total-line">Total <strong>{{money(total+shipping)}}</strong></div><button class="button green" @click="checkout=true;drawer=false">Continuar pedido <ArrowRight :size="18"/></button><small>Ambiente de demonstração. Nenhuma cobrança é realizada.</small></div></template><div v-else class="empty"><ShoppingBag :size="40"/><h3>Sua sacola espera boas escolhas.</h3><p>Sua próxima camisa ou seleção de reggae está aqui.</p><button class="button green" @click="drawer=false;choose('Todos')">Explorar coleção</button></div></aside></div>
 <div v-if="detail" class="overlay center" @click.self="detail=null"><section class="detail-modal" role="dialog" aria-modal="true" aria-labelledby="detail-title"><button class="modal-close" aria-label="Fechar detalhes" @click="detail=null"><X/></button><img :src="detail.img" :alt="detail.name"/><div><div class="eyebrow muted">{{detail.category}}</div><h2 id="detail-title">{{detail.name}}</h2><p>{{detail.description}}</p><strong>{{money(detail.price)}}</strong><p>Em até 6x de {{money(detail.price/6)}} sem juros.</p><button class="button green" @click="add(detail)">Adicionar à sacola <Plus :size="18"/></button><small>Produto e preço ilustrativos. Arte conceitual Domora.</small></div></section></div>
 <div v-if="checkout || orderDone" class="overlay center" @click.self="checkout=false;orderDone=false"><section class="checkout-modal" role="dialog" aria-modal="true" aria-labelledby="checkout-title"><button class="modal-close" aria-label="Fechar" @click="checkout=false;orderDone=false"><X/></button><template v-if="orderDone"><Check :size="42"/><h2 id="checkout-title">Boa escolha. Boa vibração.</h2><p>Pedido de demonstração concluído! Nenhum pagamento ou envio será realizado.</p><button class="button green" @click="orderDone=false">Continuar explorando</button></template><template v-else><div class="eyebrow muted">QUASE NA SUA FREQUÊNCIA</div><h2 id="checkout-title">Confira seu pedido.</h2><p>Este é um checkout demonstrativo.</p><div v-for="i in items" :key="i.id" class="checkout-row"><span>{{i.qty}} × {{i.name}}</span><strong>{{money(i.price*i.qty)}}</strong></div><div class="checkout-row"><span>Frete demonstrativo</span><span>{{shipping?money(shipping):'Grátis'}}</span></div><div class="checkout-row"><strong>Total</strong><strong>{{money(total+shipping)}}</strong></div><button class="button green" @click="finish">Concluir demonstração <Check :size="18"/></button><button class="back-link" @click="checkout=false;drawer=true">Voltar à sacola</button></template></section></div>
</template>
